changeSet.sql:
CREATE OR ALTER PROCEDURE [graph].[SynchronizeTables] AS begin
delete E from graph.AssetEdge E where E.ID not in (select ID from [Intersect]);
drop table if exists #DeleteNodes; create table #DeleteNodes (ID bigint); create clustered index CIX_DeleteNodes ON #DeleteNodes (ID)
insert into #DeleteNodes select N.ID from graph.AssetNode N where N.ID not in (select ID from Asset);
delete E from graph.AssetEdge E inner join graph.AssetNode N on E.$from_id = N.$node_id or E.$to_id = N.$node_id inner join #DeleteNodes D on D.ID = N.ID
delete N from graph.AssetNode N inner join #DeleteNodes D on D.ID = N.ID;
merge graph.AssetNode T using ( select A.ID, A.[Uid], A.AssetTypeID, T.[UID] as AssetTypeUid, A.[State], A.UpdatedOn from Asset A inner join AssetType T on T.ID = A.AssetTypeID ) S on (S.ID = T.ID) when matched and (T.UpdatedOn < S.UpdatedOn) then update set T.[State] = S.[State], T.[UpdatedOn] = S.[UpdatedOn], T.AssetTypeID = S.AssetTypeID, T.AssetTypeUid = S.AssetTypeUid when not matched by target then insert (ID, [Uid], AssetTypeID, AssetTypeUid, [State], UpdatedOn) values (ID, [Uid], AssetTypeID, AssetTypeUid, [State], UpdatedOn);
merge into graph.AssetEdge T using ( select SG.$node_id as from_id, OG.$node_id as to_id, I.ID, I.[Uid], I.IntersectTypeID, T.[Uid] as IntersectTypeUid, T.PredicateID, P.[Uid] as PredicateUid, P.[Type] as PredicateType, '<props/>' as Properties, I.[State], coalesce(I.UpdatedOn, I.CreatedOn, getutcdate()) as UpdatedOn from [Intersect] I inner join Asset SA on SA.[Object] = I.[Subject] and SA.ObjectID = I.SubjectID inner join graph.AssetNode SG on SG.ID = SA.ID inner join Asset OA on OA.[Object] = I.[Object] and OA.ObjectID = I.ObjectID inner join graph.AssetNode OG on OG.ID = OA.ID inner join IntersectType T on T.ID = I.IntersectTypeID inner join [Predicate] P on P.ID = T.PredicateID ) S on (S.ID = T.ID and S.from_id = T.$from_id and S.to_id = T.$to_id) when matched and (T.UpdatedOn < S.UpdatedOn) then update set T.IntersectTypeID = S.IntersectTypeID, T.IntersectTypeUid = S.IntersectTypeUid, T.PredicateID = S.PredicateID, T.PredicateUid = S.PredicateUid, T.PredicateType = S.PredicateType, T.[State] = S.[State] when not matched by target then insert ($from_id, $to_id, ID, Uid, IntersectTypeID, IntersectTypeUid, PredicateID, PredicateUid, PredicateType, Properties, [State], UpdatedOn) values (from_id, to_id, ID, Uid, IntersectTypeID, IntersectTypeUid, PredicateID, PredicateUid, PredicateType, Properties, [State], UpdatedOn);
drop table if exists #assetTypes; create table #assetTypes (ID bigint);
insert into #assetTypes select ID from AssetType;
while ((select count(*) from #assetTypes) > 0) begin declare @id bigint; select top 1 @id = id from #assetTypes;
exec graph.PopulatePathsForAssetType @id;
delete from #assetTypes where id = @id; end end
